const config = {
  "previewFeatures": [],
  "clientVersion": "7.8.0",
  "engineVersion": "3c6e192761c0362d496ed980de936e2f3cebcd3a",
  "activeProvider": "postgresql",
  "inlineSchema": "// TABLES ET LEURS RÔLES:\n//\n// ── ABONNEMENT ──────────────────────────────────────────────\n// Plan              → Les 3 offres Starter/Pro/Unlimited\n// Subscription      → L'abonnement actif de la company\n// Payment           → Historique des paiements Stripe\n//\n// ── SOCIÉTÉ ─────────────────────────────────────────────────\n// Company           → La société de l'installateur (tenant principal)\n// CompanySettings   → Paramètres: SMS, factures, rappels ТО, horaires\n// TradeCategory     → Domaines d'activité (clim, chaudière...) choisis à l'inscription\n//\n// ── UTILISATEURS ────────────────────────────────────────────\n// User              → Owner / Manager / Technicien\n// PushToken         → Tokens FCM pour notifications push\n// Invitation        → Invitations email pour rejoindre la company\n//\n// ── CATALOGUE ───────────────────────────────────────────────\n// CatalogItem       → Matériaux et prestations sauvegardés (réutilisables)\n// InterventionTypeItem → Types d'interventions sauvegardés (réutilisables)\n//\n// ── CLIENTS ─────────────────────────────────────────────────\n// Client            → Les clients de l'installateur\n// Equipment         → Équipements installés chez le client\n//\n// ── INTERVENTIONS ───────────────────────────────────────────\n// Intervention      → Chaque visite chez un client\n// InterventionPhoto → Photos avant/après\n//\n// ── DEVIS & FACTURES ────────────────────────────────────────\n// Quote             → Devis (D-2026-001)\n// QuoteLine         → Lignes du devis → référence CatalogItem\n// Invoice           → Facture (INV-2026-001) + PDF A4\n// InvoiceLine       → Lignes de la facture → référence CatalogItem\n//\n// ── MESSAGERIE ──────────────────────────────────────────────\n// SmsLog            → Historique SMS complet par client\n// SmsUsage          → Compteur SMS mensuel par company\n//\n// ── NOTIFICATIONS ───────────────────────────────────────────\n// Notification      → Toutes les notifs push/email/in-app\n//\n// ── DIVERS ──────────────────────────────────────────────────\n// QuoteRequest      → Demandes depuis le formulaire public\n// AuditLog          → Historique des actions (qui a fait quoi)\n//\n// ============================================================\n\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"./generated\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// ============================================================\n// ENUMS\n// ============================================================\n\nenum PlanName {\n  STARTER // €39/mois\n  PRO // €89/mois\n  UNLIMITED // €149/mois\n}\n\nenum PlanBillingCycle {\n  MONTHLY\n  ANNUAL\n}\n\nenum PlanStatus {\n  TRIALING\n  ACTIVE\n  PAST_DUE\n  CANCELLED\n  EXPIRED\n}\n\nenum UserRole {\n  SUPERADMIN\n  OWNER\n  MANAGER\n  TECHNICIAN\n}\n\nenum ClientStatus {\n  OK\n  WARNING // entretien dans < 60 jours\n  URGENT // entretien en retard\n}\n\nenum InterventionStatus {\n  PENDING\n  SCHEDULED\n  IN_PROGRESS\n  COMPLETED\n  CANCELLED\n}\n\nenum InvoiceStatus {\n  DRAFT\n  SENT\n  PAID\n  OVERDUE\n  CANCELLED\n}\n\nenum QuoteStatus {\n  DRAFT\n  SENT\n  ACCEPTED\n  REFUSED\n  EXPIRED\n}\n\nenum MessageDirection {\n  OUTGOING\n  INCOMING\n}\n\nenum NotificationType {\n  // Owner/Manager\n  NEW_CLIENT_ADDED\n  NEW_MESSAGE_RECEIVED\n  INTERVENTION_COMPLETED\n  INTERVENTION_CREATED\n  INVOICE_PAID\n  INVOICE_OVERDUE\n  MAINTENANCE_URGENT\n  MAINTENANCE_WARNING\n  NEW_QUOTE_REQUEST\n  TECHNICIAN_STARTED\n  PLAN_EXPIRING_SOON\n  PLAN_EXPIRED\n  SMS_LIMIT_WARNING\n  // Technicien\n  INTERVENTION_ASSIGNED\n  INTERVENTION_UPDATED\n  INTERVENTION_CANCELLED\n  REMINDER_TOMORROW\n  REMINDER_ONE_HOUR\n}\n\nenum NotificationChannel {\n  PUSH\n  EMAIL\n  SMS\n  IN_APP\n}\n\nenum NotificationStatus {\n  PENDING\n  SENT\n  READ\n  FAILED\n}\n\nenum InvitationStatus {\n  PENDING\n  ACCEPTED\n  EXPIRED\n  REVOKED\n}\n\nenum PaymentMethod {\n  CARD\n  SEPA\n  TRANSFER\n  CASH\n  CHEQUE\n}\n\nenum AccountingExportType {\n  MONTHLY // export mensuel\n  QUARTERLY // export trimestriel (TVA)\n  ANNUAL // export annuel\n  CUSTOM // période personnalisée\n}\n\nenum AccountingProvider {\n  PENNYLANE // pennylane.com — API disponible\n  INDY // indy.fr — API disponible\n  QUICKBOOKS // quickbooks.intuit.com\n  NONE // pas d'intégration\n}\n\nenum PreferredChannel {\n  SMS\n  EMAIL\n  WHATSAPP // V2\n}\n\nenum CatalogItemType {\n  PRODUCT // article physique: filtre, gaz R410A, tube cuivre\n  SERVICE // prestation: main d'oeuvre, déplacement\n  PACKAGE // forfait: forfait maintenance annuelle\n}\n\nenum ItemUnit {\n  UNITE\n  HEURE\n  FORFAIT\n  METRE\n  M2\n  KG\n  LITRE\n}\n\nenum SystemRole {\n  SUPER_ADMIN\n  SUPPORT\n}\n\nenum TvaRate {\n  ZERO // 0%\n  REDUIT // 5.5%\n  INTERMEDIAIRE // 10%\n  NORMAL // 20%\n}\n\n// ── PAIEMENT ET STRIPE CONNECT ───────────────────────────\nenum StripeOnboardingStatus {\n  NOT_STARTED\n  IN_PROGRESS\n  COMPLETE\n  REQUIRES_INFO\n  DISABLED\n}\n\nenum InvoicePaymentStatus {\n  PENDING\n  PAID\n  PARTIALLY_PAID\n  FAILED\n  CANCELLED\n}\n\nenum InvoicePaymentMethodType {\n  BANK_TRANSFER\n  CARD\n  OTHER\n}\n\nenum StripeFeeBearer {\n  COMPANY\n  CLIENT\n}\n\n// ── FACTURATION ÉLECTRONIQUE (RÉFORME 2026/2027) ─────────\nenum EInvoicingProviderType {\n  B2BROUTER\n  PENNYLANE\n  SAGE\n  OTHER\n}\n\nenum EInvoicingConnectionStatus {\n  DISCONNECTED\n  CONNECTED\n  ERROR\n}\n\nenum EInvoicingStatus {\n  DRAFT\n  PROCESSING\n  SENT\n  RECEIVED\n  ACCEPTED\n  REJECTED\n  CANCELLED\n  PAID\n  ERROR\n}\n\nenum EInvoicingJobStatus {\n  PENDING\n  PROCESSING\n  COMPLETED\n  FAILED\n}\n\nenum EInvoicingJobType {\n  CREATE_E_INVOICE\n  SEND_E_INVOICE\n  SYNC_E_INVOICE\n  PROCESS_WEBHOOK\n  DOWNLOAD_RECEIVED_INVOICE\n  SEND_PAYMENT_STATUS\n  RECONCILIATION\n}\n\n// ============================================================\n// PLAN\n// ─────────────────────────────────────────────────────────────\n// Définit les 3 offres disponibles.\n// Créées en seed, jamais modifiées par l'utilisateur.\n// Liées à Subscription (une company → un plan actif).\n// ============================================================\n\nmodel Plan {\n  id          String   @id @default(cuid())\n  name        PlanName @unique\n  displayName String // \"Starter\", \"Pro\", \"Unlimited\"\n\n  priceMonthly Float // 39, 89, 149\n  priceAnnual  Float // 31.20, 71.20, 119.20 (-20%)\n\n  // Limites (-1 = illimité)\n  maxClients     Int // 20, 100, -1\n  maxTechnicians Int // 1, 5, -1\n  maxSmsPerMonth Int // 50, 200, 500\n  extraSmsCost   Float @default(0.10)\n\n  // Fonctionnalités\n  hasMobileApp          Boolean @default(false)\n  hasAutoSmsReminders   Boolean @default(false) // rappels ТО automatiques\n  hasAdvancedReports    Boolean @default(false) // rapports détaillés\n  hasChorusPro          Boolean @default(false) // facturation électronique\n  hasDedicatedSmsNumber Boolean @default(false)\n  hasAccountManager     Boolean @default(false)\n  hasPrioritySupport    Boolean @default(false)\n  hasPremiumSettings    Boolean @default(false) // page Premium dans sidebar\n\n  stripeMonthlyPriceId String?\n  stripeAnnualPriceId  String?\n\n  subscriptions Subscription[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n// ============================================================\n// COMPANY\n// ─────────────────────────────────────────────────────────────\n// La société de l'installateur. C'est le tenant principal.\n// TOUT appartient à une Company (clients, interventions, etc.)\n//\n// RELATIONS:\n// → CompanySettings (1:1) — paramètres\n// → Subscription (1:1) — abonnement actif\n// → TradeCategory (1:N) — domaines d'activité choisis à l'inscription\n// → User (1:N) — équipe\n// → Client (1:N) — clients\n// → CatalogItem (1:N) — catalogue matériaux/prestations\n// → InterventionTypeItem (1:N) — types d'interventions personnalisés\n// ============================================================\n\nmodel Company {\n  id              String  @id @default(cuid())\n  name            String\n  siret           String? @unique // 14 chiffres\n  siren           String? @unique // 9 chiffres (= siret[0..8])\n  tvaNumber       String? // FR + 11 chiffres (calculé depuis SIREN)\n  legalForm       String? // \"SARL\", \"SAS\", \"SA\", \"EI\", \"Auto-entrepreneur\", \"SNC\"...\n  rcsNumber       String? // Numéro RCS + ville greffe ex: \"Paris B 123 456 789\"\n  shareCapital    String? // Capital social ex: \"10 000€\" (obligatoire SARL/SAS/SA)\n  nafCode         String? // Code NAF/APE ex: \"4322A\" (récupéré depuis API SIRENE)\n  isTvaFranchise  Boolean @default(false) // Auto-entrepreneur sans TVA → mention art.293B CGI\n  isSubcontractor Boolean @default(false) // Sous-traitant BTP → autoliquidation TVA\n  phone           String?\n  email           String?\n  address         String?\n  city            String?\n  postalCode      String?\n  logoUrl         String?\n  signatureUrl    String?\n  website         String?\n  slug            String? @unique // \"dupont-climatisation\" pour formulaire public\n\n  // Numéro Twilio virtuel pour les SMS\n  smsNumber String?\n\n  // ── STRIPE CONNECT (paiement en ligne factures) ───────────\n  // L'installateur connecte son propre compte Stripe\n  // L'argent va directement sur son compte bancaire\n  stripeAccountId        String?                @unique // ex: \"acct_1ABC...\"\n  stripeAccountStatus    String? // \"pending\", \"active\", \"restricted\"\n  onlinePaymentEnabled   Boolean                @default(false) // true quand Stripe connecté\n  stripeOnboardingStatus StripeOnboardingStatus @default(NOT_STARTED)\n  stripeChargesEnabled   Boolean                @default(false)\n  stripePayoutsEnabled   Boolean                @default(false)\n  stripeDetailsSubmitted Boolean                @default(false)\n  stripeConnectedAt      DateTime?\n\n  // Relations\n  users               User[]\n  clients             Client[]\n  interventions       Intervention[]\n  invoices            Invoice[]\n  quotes              Quote[]\n  smsLogs             SmsLog[]\n  whatsappConnections WhatsAppConnection[]\n  emailConnections    EmailConnection[]\n  notifications       Notification[]\n  invitations         Invitation[]\n  subscription        Subscription?\n  settings            CompanySettings?\n  smsUsage            SmsUsage[]\n  auditLogs           AuditLog[]\n  quoteRequests       QuoteRequest[]\n  catalogItems        CatalogItem[]\n  interventionTypes   InterventionTypeItem[]\n  tradeCategories     CompanyTradeCategory[]\n  invoiceTransactions InvoiceTransaction[]\n  bankConnection      BankConnection?\n  bankAccounts        BankAccount[]\n  bankTransactions    BankTransaction[]\n\n  createdAt             DateTime               @default(now())\n  updatedAt             DateTime               @updatedAt\n  accountingExports     AccountingExport[]\n  tvaSummaries          TvaSummary[]\n  accountingIntegration AccountingIntegration?\n  einvoicingConnection  EInvoicingConnection?\n  receivedInvoices      ReceivedInvoice[]\n  einvoicingEvents      EInvoicingEvent[]\n  einvoicingJobs        EInvoicingJob[]\n}\n\n// ============================================================\n// COMPANY TRADE CATEGORY\n// ─────────────────────────────────────────────────────────────\n// Domaines d'activité choisis par l'installateur à l'inscription.\n// Exemples: Pompe à chaleur, VMC, Chaudière gaz...\n//\n// RELATIONS:\n// → Company (N:1) — appartient à une company\n// → TradeCategory (N:1) — référence le domaine du catalogue global\n//\n// Lors de l'inscription, l'installateur choisit un ou plusieurs\n// domaines depuis la liste prédéfinie dans TradeCategory.\n// ============================================================\n\nmodel CompanyTradeCategory {\n  id              String        @id @default(cuid())\n  companyId       String\n  company         Company       @relation(fields: [companyId], references: [id], onDelete: Cascade)\n  tradeCategoryId String\n  tradeCategory   TradeCategory @relation(fields: [tradeCategoryId], references: [id])\n\n  createdAt DateTime @default(now())\n\n  @@unique([companyId, tradeCategoryId])\n}\n\n// ============================================================\n// TRADE CATEGORY\n// ─────────────────────────────────────────────────────────────\n// Liste globale des domaines d'activité disponibles.\n// Créée en seed. L'installateur choisit parmi cette liste.\n//\n// Exemples depuis la liste fournie:\n//   - Pompe à chaleur : chauffage\n//   - Chauffe-Eau Thermodynamique\n//   - Ventilation mécanique (VMC)\n//   - Panneaux solaires photovoltaïques\n//   - Chaudière condensation gaz ou fioul\n//   - Poêle ou insert bois\n//   etc.\n//\n// RELATIONS:\n// → CompanyTradeCategory (1:N) — companies qui ont ce domaine\n// ============================================================\n\nmodel TradeCategory {\n  id          String  @id @default(cuid())\n  name        String  @unique // \"Pompe à chaleur : chauffage\"\n  slug        String  @unique // \"pompe-a-chaleur-chauffage\"\n  description String?\n  icon        String? // emoji ou nom d'icône\n  isActive    Boolean @default(true)\n  sortOrder   Int     @default(0) // ordre d'affichage\n\n  companies CompanyTradeCategory[]\n\n  createdAt DateTime @default(now())\n}\n\n// ============================================================\n// SUBSCRIPTION\n// ─────────────────────────────────────────────────────────────\n// L'abonnement actif de la company. Une seule par company.\n//\n// RELATIONS:\n// → Company (1:1) — appartient à une company\n// → Plan (N:1) — quel plan est actif\n// → Payment (1:N) — historique des paiements\n// ============================================================\n\nmodel Subscription {\n  id        String  @id @default(cuid())\n  companyId String  @unique\n  company   Company @relation(fields: [companyId], references: [id], onDelete: Cascade)\n  planId    String\n  plan      Plan    @relation(fields: [planId], references: [id])\n\n  status PlanStatus       @default(TRIALING)\n  cycle  PlanBillingCycle @default(MONTHLY)\n\n  trialEndsAt        DateTime?\n  currentPeriodStart DateTime?\n  currentPeriodEnd   DateTime?\n  cancelledAt        DateTime?\n\n  stripeCustomerId     String? @unique\n  stripeSubscriptionId String? @unique\n\n  // Compteur SMS mensuel (reset le 1er du mois via cron)\n  smsUsedThisMonth Int       @default(0)\n  smsResetAt       DateTime?\n\n  payments Payment[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n// ============================================================\n// PAYMENT\n// ─────────────────────────────────────────────────────────────\n// Historique des paiements Stripe.\n// Créé automatiquement via webhook Stripe.\n//\n// RELATIONS:\n// → Subscription (N:1) — rattaché à un abonnement\n// ============================================================\n\nmodel Payment {\n  id             String       @id @default(cuid())\n  subscriptionId String\n  subscription   Subscription @relation(fields: [subscriptionId], references: [id])\n\n  amount   Float\n  currency String         @default(\"EUR\")\n  status   String // succeeded, failed, pending\n  method   PaymentMethod?\n\n  stripePaymentIntentId String? @unique\n  stripeInvoiceUrl      String? // lien vers la facture Stripe\n\n  paidAt    DateTime?\n  createdAt DateTime  @default(now())\n}\n\n// ============================================================\n// COMPANY SETTINGS\n// ─────────────────────────────────────────────────────────────\n// Tous les paramètres de la company. Une seule ligne par company.\n//\n// CONTIENT:\n// - Paramètres SMS (rappels ТО, templates, signature)\n// - Délai de rappel ТО (configurable en Premium)\n// - Notifications (quelles notifs, quels canaux)\n// - Numérotation auto des factures/devis\n// - Paramètres PDF (pied de page, conditions)\n// - Horaires de travail\n//\n// RELATIONS:\n// → Company (1:1) — appartient à une company\n// ============================================================\n\nmodel CompanySettings {\n  id        String  @id @default(cuid())\n  companyId String  @unique\n  company   Company @relation(fields: [companyId], references: [id], onDelete: Cascade)\n\n  // ── CANAUX PAR TYPE DE MESSAGE ───────────────────────────\n  // Définit quel canal utiliser par défaut selon le type\n  // Peut être écrasé par le canal préféré du client\n  defaultChannelReminder PreferredChannel @default(SMS)\n  defaultChannelQuote    PreferredChannel @default(EMAIL)\n  defaultChannelInvoice  PreferredChannel @default(EMAIL)\n  defaultChannelConfirm  PreferredChannel @default(SMS)\n\n  // ── SMS RAPPELS ТО ────────────────────────────────────────\n  // Configurable uniquement en plan Pro/Unlimited (hasPremiumSettings)\n  smsReminderEnabled       Boolean @default(true)\n  // Délai en jours avant le ТО (configurable en Premium: 7, 14, 30, 60, 90)\n  smsDaysBefore            Int     @default(30)\n  // Deuxième rappel (optionnel, Premium)\n  smsSecondReminderEnabled Boolean @default(false)\n  smsSecondReminderDays    Int     @default(7) // 7 jours avant\n  // Template SMS personnalisé\n  smsReminderTemplate      String?\n  // Signature en fin de SMS\n  smsSignature             String? // \"— Dupont Climatisation\"\n\n  // ── NOTIFICATIONS OWNER/MANAGER ───────────────────────────\n  notifyNewClient         Boolean @default(true)\n  notifyNewMessage        Boolean @default(true)\n  notifyInterventionDone  Boolean @default(true)\n  notifyInvoicePaid       Boolean @default(true)\n  notifyUrgentMaintenance Boolean @default(true)\n  notifyQuoteRequest      Boolean @default(true)\n  notifyPlanExpiring      Boolean @default(true)\n  notifySmsLimit          Boolean @default(true)\n\n  // ── NOTIFICATIONS TECHNICIEN ──────────────────────────────\n  notifyTechAssigned    Boolean @default(true)\n  notifyTechUpdated     Boolean @default(true)\n  notifyTechCancelled   Boolean @default(true)\n  notifyTechReminder24h Boolean @default(true)\n  notifyTechReminder1h  Boolean @default(true)\n\n  ownerChannels NotificationChannel[] @default([PUSH, IN_APP])\n  techChannels  NotificationChannel[] @default([PUSH, IN_APP])\n\n  // ── NUMÉROTATION AUTO ─────────────────────────────────────\n  invoicePrefix     String @default(\"INV\") // INV-2026-001\n  invoiceNextNumber Int    @default(1)\n  quotePrefix       String @default(\"D\") // D-2026-001\n  quoteNextNumber   Int    @default(1)\n\n  invoiceFooter         String? // texte pied de page PDF\n  invoiceConditions     String? // conditions de paiement\n  invoiceColor          String? @default(\"#556B2F\") // couleur principale PDF factures & devis\n  documentCustomization Json? // style visuel par défaut des documents (couleurs, structure, polices, visibilité)\n  defaultTvaRate        Float   @default(20)\n  defaultPaymentDays    Int     @default(30) // délai paiement facture\n\n  // ── DEVIS ─────────────────────────────────────────────────\n  defaultValidDays Int @default(30) // validité devis en jours\n\n  // ── HORAIRES ─────────────────────────────────────────────\n  workStartHour Int   @default(8)\n  workEndHour   Int   @default(18)\n  workDays      Int[] @default([1, 2, 3, 4, 5]) // 1=Lun, 7=Dim\n\n  // ── COORDONNÉES BANCAIRES (RIB / IBAN FACTURES & DEVIS) ──\n  bankName             String? // \"La Banque Postale\", \"BNP Paribas\", \"Boursorama Pro\", etc.\n  bankIban             String? // \"FR76 3000 3020 5001 2345 6789 012\"\n  bankBic              String? // \"BNPAFRPPXXX\"\n  bankAccountOwner     String? // \"Dupont Climatisation SAS\"\n  bankTransferEnabled  Boolean         @default(true)\n  stripePaymentEnabled Boolean         @default(false)\n  stripeFeeBearer      StripeFeeBearer @default(COMPANY)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n// ============================================================\n// USER\n// ─────────────────────────────────────────────────────────────\n// Membres de la company: Owner, Manager, Technicien.\n//\n// RELATIONS:\n// → Company (N:1) — appartient à une company\n// → PushToken (1:N) — tokens FCM pour push\n// → Intervention (1:N) — interventions assignées (technicien)\n// → Notification (1:N) — ses notifications\n// ============================================================\n\nmodel User {\n  id        String  @id @default(cuid())\n  companyId String\n  company   Company @relation(fields: [companyId], references: [id], onDelete: Cascade)\n\n  email     String   @unique\n  password  String\n  firstName String\n  lastName  String\n  phone     String?\n  avatarUrl String?\n  role      UserRole @default(TECHNICIAN)\n  isActive  Boolean  @default(true)\n\n  // Auth & Security tokens\n  refreshTokenHash    String?\n  emailVerified       Boolean   @default(false)\n  emailVerifyToken    String?\n  passwordResetToken  String?\n  passwordResetExpiry DateTime?\n  lastLoginAt         DateTime?\n\n  // ── DOUBLE AUTHENTIFICATION (2FA) ─────────────\n  twoFactorEnabled Boolean   @default(false)\n  twoFactorSecret  String?\n  twoFactorCode    String?\n  twoFactorExpiry  DateTime?\n\n  pushTokens           PushToken[]\n  interventions        Intervention[] @relation(\"TechnicianInterventions\")\n  notifications        Notification[]\n  createdClients       Client[]       @relation(\"ClientCreatedBy\")\n  createdInterventions Intervention[] @relation(\"InterventionCreatedBy\")\n  auditLogs            AuditLog[]\n  sessions             UserSession[]\n  loginHistories       LoginHistory[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n// ============================================================\n// USER SESSION\n// ─────────────────────────────────────────────────────────────\n// Sessions actives par appareil pour l'utilisateur.\n// ============================================================\n\nmodel UserSession {\n  id              String   @id @default(cuid())\n  userId          String\n  user            User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  device          String // e.g. \"MacBook Pro 16\\\" (macOS)\"\n  browser         String // e.g. \"Google Chrome 127.0\"\n  ip              String // e.g. \"82.64.120.45\"\n  location        String? // e.g. \"Nice, France\"\n  tokenIdentifier String?\n  isCurrent       Boolean  @default(false)\n  lastActiveAt    DateTime @default(now())\n  createdAt       DateTime @default(now())\n\n  @@index([userId])\n}\n\n// ============================================================\n// LOGIN HISTORY\n// ─────────────────────────────────────────────────────────────\n// Historique des connexions récentes.\n// ============================================================\n\nmodel LoginHistory {\n  id        String   @id @default(cuid())\n  userId    String?\n  user      User?    @relation(fields: [userId], references: [id], onDelete: Cascade)\n  email     String\n  ip        String\n  device    String\n  status    String   @default(\"Succès\") // \"Succès\", \"Échec - Mot de passe incorrect\", etc.\n  createdAt DateTime @default(now())\n\n  @@index([userId])\n  @@index([email])\n}\n\n// ============================================================\n// PUSH TOKEN\n// ─────────────────────────────────────────────────────────────\n// Tokens FCM pour notifications push mobile/web.\n// Un user peut avoir plusieurs tokens (iPhone + Chrome + Android).\n//\n// RELATIONS:\n// → User (N:1) — appartient à un user\n// ============================================================\n\nmodel PushToken {\n  id        String   @id @default(cuid())\n  userId    String\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  token     String   @unique\n  device    String? // \"iPhone 15 Pro\"\n  platform  String? // \"ios\", \"android\", \"web\"\n  isActive  Boolean  @default(true)\n  createdAt DateTime @default(now())\n}\n\n// ============================================================\n// INVITATION\n// ─────────────────────────────────────────────────────────────\n// Invitation email pour rejoindre la company.\n// Token unique dans le lien, expire après 7 jours.\n//\n// RELATIONS:\n// → Company (N:1) — appartient à une company\n// ============================================================\n\nmodel Invitation {\n  id        String  @id @default(cuid())\n  companyId String\n  company   Company @relation(fields: [companyId], references: [id], onDelete: Cascade)\n\n  email       String\n  role        UserRole         @default(TECHNICIAN)\n  token       String           @unique @default(cuid())\n  status      InvitationStatus @default(PENDING)\n  invitedById String? // userId de celui qui a invité\n  expiresAt   DateTime // now() + 7 jours\n  acceptedAt  DateTime?\n  revokedAt   DateTime?\n\n  createdAt DateTime @default(now())\n\n  @@unique([companyId, email])\n}\n\n// ============================================================\n// CATALOG ITEM\n// ─────────────────────────────────────────────────────────────\n// Catalogue des matériaux et prestations de la company.\n// Sauvegardé automatiquement quand l'installateur ajoute\n// un nouveau produit/service dans un devis ou une facture.\n//\n// LOGIQUE:\n// - L'installateur crée une facture et tape \"Tube cuivre 1/2\" à 12€\n// - → CatalogItem est créé automatiquement\n// - La prochaine fois, \"Tube cuivre 1/2\" apparaît dans la liste\n// - Il peut choisir depuis la liste ou modifier le prix pour cette ligne\n// - usageCount s'incrémente à chaque utilisation\n//\n// RELATIONS:\n// → Company (N:1) — catalogue propre à chaque company\n// → QuoteLine (1:N) — lignes de devis qui utilisent cet article\n// → InvoiceLine (1:N) — lignes de facture qui utilisent cet article\n// ============================================================\n\nmodel CatalogItem {\n  id        String  @id @default(cuid())\n  companyId String\n  company   Company @relation(fields: [companyId], references: [id], onDelete: Cascade)\n\n  name        String // \"Tube cuivre 1/2\", \"Main d'oeuvre\"\n  description String?\n  reference   String? // référence interne \"REF-001\"\n  type        CatalogItemType // PRODUCT, SERVICE, PACKAGE\n\n  defaultPrice Float // prix unitaire par défaut\n  tvaRate      Float    @default(20)\n  unit         ItemUnit @default(UNITE)\n\n  isActive   Boolean @default(true) // archivable\n  isFavorite Boolean @default(false) // épinglé en haut\n  usageCount Int     @default(0) // tri par popularité\n\n  quoteLines   QuoteLine[]\n  invoiceLines InvoiceLine[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([companyId])\n  @@index([companyId, isActive])\n  @@index([companyId, usageCount])\n}\n\n// ============================================================\n// INTERVENTION TYPE ITEM\n// ─────────────────────────────────────────────────────────────\n// Types d'interventions personnalisés par company.\n// Sauvegardé automatiquement quand l'installateur crée\n// un nouveau type dans un formulaire.\n//\n// TYPES PAR DÉFAUT (créés en seed par company):\n//   Installation, Maintenance annuelle, Dépannage,\n//   Contrôle, Mise en service, Désinstallation\n//\n// LOGIQUE:\n// - L'installateur tape un nouveau type \"Mise en route\"\n// - → InterventionTypeItem est créé\n// - La prochaine fois, \"Mise en route\" est dans la liste\n//\n// RELATIONS:\n// → Company (N:1) — types propres à chaque company\n// → Intervention (1:N) — interventions de ce type\n// → Invoice (1:N) — factures de ce type\n// ============================================================\n\nmodel InterventionTypeItem {\n  id        String  @id @default(cuid())\n  companyId String\n  company   Company @relation(fields: [companyId], references: [id], onDelete: Cascade)\n\n  name       String // \"Maintenance annuelle\", \"Dépannage\", \"Mise en route\"\n  isDefault  Boolean @default(false) // créé par le système, non supprimable\n  isActive   Boolean @default(true)\n  usageCount Int     @default(0)\n  sortOrder  Int     @default(0)\n\n  interventions Intervention[]\n  invoices      Invoice[]\n  quotes        Quote[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([companyId, name])\n  @@index([companyId])\n}\n\n// ============================================================\n// CLIENT\n// ─────────────────────────────────────────────────────────────\n// Les clients de l'installateur.\n//\n// STATUT (calculé chaque nuit par cron):\n//   OK      → prochain entretien dans > 60 jours\n//   WARNING → prochain entretien dans < 60 jours\n//   URGENT  → entretien en retard\n//\n// RELATIONS:\n// → Company (N:1) — appartient à une company\n// → Equipment (1:N) — ses équipements\n// → Intervention (1:N) — ses interventions\n// → Invoice (1:N) — ses factures\n// → Quote (1:N) — ses devis\n// → SmsLog (1:N) — historique SMS\n// ============================================================\n\nmodel Client {\n  id        String  @id @default(cuid())\n  companyId String\n  company   Company @relation(fields: [companyId], references: [id], onDelete: Cascade)\n\n  createdById String?\n  createdBy   User?   @relation(\"ClientCreatedBy\", fields: [createdById], references: [id])\n\n  firstName   String\n  lastName    String\n  companyName String? // si c'est une société (B2B)\n  phone       String\n  email       String?\n  address     String\n  city        String?\n  postalCode  String?\n  notes       String? // code digicode, remarques\n  isActive    Boolean      @default(true)\n  status      ClientStatus @default(OK)\n  source      String? // \"appel\", \"site_web\", \"manuel\", \"parrainage\"\n\n  // ── CANAL DE COMMUNICATION PRÉFÉRÉ ──────────────────────\n  // Défini dans la fiche client, utilisé pour tous les messages auto\n  preferredChannel   PreferredChannel  @default(SMS)\n  // Canal spécifique par type de message (optionnel, écrase preferredChannel)\n  channelForReminder PreferredChannel? // rappels ТО → défaut: SMS\n  channelForQuote    PreferredChannel? // devis → défaut: EMAIL\n  channelForInvoice  PreferredChannel? // factures → défaut: EMAIL\n  channelForConfirm  PreferredChannel? // confirmation RDV → défaut: SMS\n\n  // ── DONNÉES B2B (si client professionnel) ────────────────\n  sirenNumber        String? // 🆕 OBLIGATOIRE sur facture B2B depuis sept. 2026\n  clientTvaNumber    String? // N° TVA intracommunautaire du client (B2B UE)\n  clientLegalForm    String? // Forme juridique du client si société\n  clientNafCode      String? // Code NAF (récupéré depuis API SIRENE auto)\n  // Adresse de livraison si différente de l'adresse de facturation\n  hasDeliveryAddress Boolean @default(false)\n  deliveryAddress    String?\n  deliveryCity       String?\n  deliveryPostalCode String?\n\n  equipment     Equipment[]\n  interventions Intervention[]\n  invoices      Invoice[]\n  quotes        Quote[]\n  smsLogs       SmsLog[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([companyId])\n  @@index([companyId, status])\n  @@index([phone])\n}\n\n// ============================================================\n// EQUIPMENT\n// ─────────────────────────────────────────────────────────────\n// Équipements installés chez le client.\n// Un client peut avoir plusieurs équipements.\n//\n// LOGIQUE ТО:\n// - installDate + serviceInterval mois = nextServiceDate\n// - Quand une intervention COMPLETED → lastServiceDate = now()\n//   → nextServiceDate recalculée automatiquement\n// - Cron nuit → met à jour client.status selon nextServiceDate\n//\n// RELATIONS:\n// → Client (N:1) — appartient à un client\n// → Intervention (1:N) — interventions sur cet équipement\n// ============================================================\n\nmodel Equipment {\n  id       String @id @default(cuid())\n  clientId String\n  client   Client @relation(fields: [clientId], references: [id], onDelete: Cascade)\n\n  // Identification\n  brand        String // \"Daikin\", \"Mitsubishi\"\n  model        String? // \"3.5kW Inverter\"\n  serialNumber String? // \"DK-2024-1234\"\n  power        String? // \"3.5kW\"\n  location     String? // \"Salon\", \"Chambre 1\"\n\n  // Domaine (lié au TradeCategory slug)\n  tradeSlug String? // \"pompe-a-chaleur\", \"climatisation\"...\n\n  // Dates\n  installDate     DateTime?\n  warrantyExpiry  DateTime?\n  lastServiceDate DateTime?\n  nextServiceDate DateTime? // calculé auto\n  serviceInterval Int       @default(12) // mois entre entretiens\n\n  isActive Boolean @default(true)\n  notes    String?\n\n  interventions Intervention[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([clientId])\n  @@index([nextServiceDate]) // utilisé par le cron de rappel\n}\n\n// ============================================================\n// INTERVENTION\n// ─────────────────────────────────────────────────────────────\n// Chaque visite chez un client.\n//\n// CYCLE DE VIE:\n// PENDING → assigné → SCHEDULED → technicien démarre → IN_PROGRESS\n//   → technicien complète → COMPLETED (ou CANCELLED)\n//\n// À COMPLETED:\n// - Met à jour Equipment.lastServiceDate\n// - Recalcule Equipment.nextServiceDate\n// - Envoie notif INTERVENTION_COMPLETED au owner\n//\n// RELATIONS:\n// → Company (N:1)\n// → Client (N:1)\n// → Equipment (N:1) optionnel\n// → User/technicien (N:1) optionnel\n// → InterventionTypeItem (N:1) — type sauvegardé\n// → Invoice (1:1) optionnel\n// → Quote (1:1) optionnel\n// → InterventionPhoto (1:N)\n// ============================================================\n\nmodel Intervention {\n  id        String  @id @default(cuid())\n  companyId String\n  company   Company @relation(fields: [companyId], references: [id], onDelete: Cascade)\n\n  clientId     String\n  client       Client     @relation(fields: [clientId], references: [id])\n  equipmentId  String?\n  equipment    Equipment? @relation(fields: [equipmentId], references: [id])\n  technicianId String?\n  technician   User?      @relation(\"TechnicianInterventions\", fields: [technicianId], references: [id])\n  createdById  String?\n  createdBy    User?      @relation(\"InterventionCreatedBy\", fields: [createdById], references: [id])\n\n  // Type sauvegardé dans le catalogue de types\n  interventionTypeId String?\n  interventionType   InterventionTypeItem? @relation(fields: [interventionTypeId], references: [id])\n\n  status InterventionStatus @default(PENDING)\n\n  // Planification\n  scheduledAt       DateTime?\n  estimatedDuration Int? // minutes\n  startedAt         DateTime?\n  completedAt       DateTime?\n\n  // Détails\n  title       String\n  description String? // instructions pour le technicien\n  address     String\n  city        String?\n  accessCode  String? // code digicode/portail\n\n  // Compte-rendu technicien (saisi après l'intervention)\n  techNotes     String?\n  materialsUsed String?\n\n  // Signature client\n  clientSignature String? // base64\n  clientSignedAt  DateTime?\n\n  photos  InterventionPhoto[]\n  invoice Invoice?\n  quote   Quote?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([companyId])\n  @@index([technicianId])\n  @@index([scheduledAt])\n  @@index([status])\n  @@index([companyId, status])\n}\n\n// ============================================================\n// INTERVENTION PHOTO\n// ─────────────────────────────────────────────────────────────\n// Photos avant/après prises par le technicien sur place.\n// Stockées sur Cloudinary.\n//\n// RELATIONS:\n// → Intervention (N:1) — appartient à une intervention\n// ============================================================\n\nmodel InterventionPhoto {\n  id             String       @id @default(cuid())\n  interventionId String\n  intervention   Intervention @relation(fields: [interventionId], references: [id], onDelete: Cascade)\n  url            String // URL Cloudinary\n  type           String       @default(\"after\") // \"before\" | \"after\"\n  caption        String?\n  createdAt      DateTime     @default(now())\n}\n\n// ============================================================\n// QUOTE (Devis)\n// ─────────────────────────────────────────────────────────────\n// Document commercial envoyé au client avant les travaux.\n// Numéroté automatiquement: D-2026-001\n// Peut être converti en facture une fois accepté.\n//\n// RELATIONS:\n// → Company (N:1)\n// → Client (N:1)\n// → InterventionTypeItem (N:1) — type d'intervention\n// → Intervention (1:1) optionnel\n// → QuoteLine (1:N) — lignes du devis\n// ============================================================\n\nmodel Quote {\n  id        String  @id @default(cuid())\n  companyId String\n  company   Company @relation(fields: [companyId], references: [id], onDelete: Cascade)\n\n  clientId       String\n  client         Client        @relation(fields: [clientId], references: [id])\n  interventionId String?       @unique\n  intervention   Intervention? @relation(fields: [interventionId], references: [id])\n\n  // Type d'intervention sauvegardé\n  interventionTypeId String?\n  interventionType   InterventionTypeItem? @relation(fields: [interventionTypeId], references: [id])\n\n  number String // D-2026-001 généré auto\n  status QuoteStatus @default(DRAFT)\n\n  // Montants (calculés depuis les lignes)\n  amountHT  Float\n  tvaRate   Float @default(20)\n  amountTTC Float\n\n  // Métadonnées\n  subject               String? // \"Installation clim Daikin salon\"\n  notes                 String? // notes internes\n  conditions            String? // visibles sur le PDF\n  documentCustomization Json? // style visuel personnalisé du devis\n\n  validUntil DateTime?\n  acceptedAt DateTime?\n  refusedAt  DateTime?\n\n  // ── MENTIONS LÉGALES DEVIS ────────────────────────────────\n  // Date de réalisation prévue\n  serviceDate       DateTime?\n  operationType     String?   @default(\"services\")\n  // Conditions d'acompte\n  depositPercent    Float? // % d'acompte ex: 30 → \"Acompte de 30% à la commande\"\n  depositAmount     Float? // Montant calculé auto\n  // Conditions de règlement sur le devis\n  paymentConditions String? // \"Solde à la livraison\"\n\n  // ── SIGNATURE ÉLECTRONIQUE ────────────────────────────────\n  // Token unique envoyé dans le lien email au client\n  // Ex: climpro.fr/sign/quote/abc123xyz\n  signatureToken       String?   @unique\n  signatureTokenExpiry DateTime? // expire après 30 jours\n  signedAt             DateTime? // quand le client a signé\n  signatureUrl         String? // URL du PDF signé (Cloudinary)\n  signatureIp          String? // IP du client au moment de la signature\n  paidAt               DateTime? // quand le client a payé le devis\n\n  // ── ENVOI EMAIL ───────────────────────────────────────────\n  emailSentAt DateTime? // quand l'email a été envoyé\n  emailSentTo String? // email destinataire\n\n  // ── RAPPELS AUTOMATIQUES (cron) ───────────────────────────\n  // Si devis non signé après X jours → rappel automatique\n  reminder1SentAt DateTime? // J+7 après envoi\n  reminder2SentAt DateTime? // J+14 après envoi\n\n  issuedAt DateTime @default(now())\n\n  lines QuoteLine[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([companyId])\n  @@index([clientId])\n  @@index([status])\n}\n\n// ============================================================\n// QUOTE LINE\n// ─────────────────────────────────────────────────────────────\n// Une ligne dans le devis.\n//\n// LOGIQUE CATALOGUE:\n// catalogItemId = \"abc\" → article choisi depuis le catalogue\n// catalogItemId = null  → saisi manuellement\n//   → si saveToCtaolog=true (frontend) → bakcend crée CatalogItem\n//\n// Les données (description, prix) sont COPIÉES à la création.\n// Modifier le catalogue ne modifie PAS les devis existants.\n//\n// RELATIONS:\n// → Quote (N:1) — appartient à un devis\n// → CatalogItem (N:1) optionnel — article du catalogue\n// ============================================================\n\nmodel QuoteLine {\n  id      String @id @default(cuid())\n  quoteId String\n  quote   Quote  @relation(fields: [quoteId], references: [id], onDelete: Cascade)\n\n  catalogItemId String?\n  catalogItem   CatalogItem? @relation(fields: [catalogItemId], references: [id])\n\n  // Données copiées (indépendantes du catalogue après création)\n  description String\n  reference   String?\n  quantity    Float    @default(1)\n  unitPrice   Float\n  tvaRate     Float    @default(20)\n  unit        ItemUnit @default(UNITE)\n  discount    Float    @default(0) // remise en %\n  total       Float // quantity * unitPrice * (1 - discount/100)\n\n  position Int @default(0) // ordre des lignes\n\n  createdAt DateTime @default(now())\n\n  @@index([quoteId])\n  @@index([catalogItemId])\n}\n\n// ============================================================\n// INVOICE (Facture)\n// ─────────────────────────────────────────────────────────────\n// Numérotée automatiquement: INV-2026-001\n// PDF A4 généré et stocké sur Cloudinary/S3.\n// Peut être créée depuis un devis (convertToInvoice)\n// ou directement depuis le formulaire.\n//\n// RELATIONS:\n// → Company (N:1)\n// → Client (N:1)\n// → InterventionTypeItem (N:1) — type d'intervention\n// → Intervention (1:1) optionnel\n// → InvoiceLine (1:N) — lignes\n// ============================================================\n\nmodel Invoice {\n  id        String  @id @default(cuid())\n  companyId String\n  company   Company @relation(fields: [companyId], references: [id], onDelete: Cascade)\n\n  clientId       String\n  client         Client        @relation(fields: [clientId], references: [id])\n  interventionId String?       @unique\n  intervention   Intervention? @relation(fields: [interventionId], references: [id])\n\n  // Lien vers le devis d'origine si convertie\n  sourceQuoteId String? @unique\n\n  // Type d'intervention sauvegardé\n  interventionTypeId String?\n  interventionType   InterventionTypeItem? @relation(fields: [interventionTypeId], references: [id])\n\n  number String // INV-2026-001\n  status InvoiceStatus @default(DRAFT)\n\n  // Montants\n  amountHT   Float\n  tvaRate    Float @default(20)\n  amountTTC  Float\n  amountPaid Float @default(0)\n\n  // ── MENTIONS LÉGALES OBLIGATOIRES (loi française 2026) ──\n  // Date de réalisation de la prestation (≠ date d'émission)\n  serviceDate       DateTime?\n  // 🆕 Nature de l'opération (obligatoire facturation électronique)\n  operationType     String?   @default(\"services\") // \"services\", \"biens\", \"mixte\"\n  // Taux pénalités de retard (obligatoire B2B, minimum 3× taux légal)\n  penaltyRate       Float     @default(10) // % annuel, ex: 10%\n  // Indemnité forfaitaire de recouvrement (obligatoire B2B depuis loi LME)\n  recoveryFee       Float     @default(40) // 40€ fixe par la loi\n  // Conditions d'escompte (obligatoire de mentionner même si absent)\n  discountTerms     String?   @default(\"Aucun escompte pour paiement anticipé\")\n  // Option TVA sur les débits (si applicable)\n  tvaOnDebit        Boolean   @default(false)\n  // Si client auto-entrepreneur → mention art. 293 B CGI\n  isTvaFranchise    Boolean   @default(false)\n  // Si sous-traitant BTP → autoliquidation TVA\n  isAutoLiquidation Boolean   @default(false)\n  // N° bon de commande si établi par le client\n  orderNumber       String?\n\n  // Description libre des travaux effectués\n  workDescription String? // \"Nettoyage filtres, vérification circuit frigorigène...\"\n\n  subject               String?\n  notes                 String? // notes internes (non visibles sur PDF)\n  conditions            String? // visibles sur PDF\n  documentCustomization Json? // style visuel personnalisé de la facture\n\n  paymentMethod PaymentMethod?\n  paymentRef    String?\n\n  // PDF\n  pdfUrl String? // URL du PDF généré (Cloudinary/S3)\n\n  // ── PAIEMENT EN LIGNE (optionnel — Stripe) & VIREMENT ─────\n  // Activé si owner veut proposer paiement par carte ou virement\n  paymentStatus           InvoicePaymentStatus      @default(PENDING)\n  invoicePaymentMethod    InvoicePaymentMethodType?\n  bankTransferEnabled     Boolean                   @default(true)\n  stripeEnabled           Boolean                   @default(false)\n  onlinePaymentEnabled    Boolean                   @default(false)\n  // Stripe Payment Intent créé quand client clique \"Payer en ligne\"\n  stripePaymentIntentId   String?                   @unique\n  // Lien Stripe Checkout envoyé au client\n  stripeCheckoutUrl       String?\n  // Session Stripe Checkout ID\n  stripeCheckoutSessionId String?                   @unique\n  // Token unique pour page de paiement public\n  // Ex: climpro.fr/pay/invoice/abc123xyz\n  paymentToken            String?                   @unique\n  paymentTokenExpiry      DateTime?\n  // Quand le client a ouvert le lien de paiement\n  paymentLinkOpenedAt     DateTime?\n\n  issuedAt DateTime  @default(now())\n  dueAt    DateTime?\n  paidAt   DateTime?\n\n  // ── ENVOI EMAIL ───────────────────────────────────────────\n  emailSentAt DateTime? // quand l'email a été envoyé\n  emailSentTo String? // email destinataire\n\n  // ── RAPPELS AUTOMATIQUES (cron) ───────────────────────────\n  // Si facture non payée → rappel automatique\n  reminder1SentAt DateTime? // J+7 après dueAt\n  reminder2SentAt DateTime? // J+14 après dueAt\n  reminderSentAt  DateTime? // dernier rappel manuel (bouton \"Relancer\")\n\n  lines            InvoiceLine[]\n  paymentEvents    InvoicePaymentEvent[]\n  transactions     InvoiceTransaction[]\n  bankTransactions BankTransaction[]\n\n  // ── FACTURATION ÉLECTRONIQUE (RÉFORME 2026/2027) ─────────\n  einvoicingStatus         EInvoicingStatus?       @default(DRAFT)\n  einvoicingProvider       EInvoicingProviderType?\n  providerInvoiceId        String?\n  einvoicingSentAt         DateTime?\n  einvoicingProcessedAt    DateTime?\n  einvoicingTransmissionId String?\n  einvoicingError          String?\n  einvoicingRawPayload     Json?\n\n  einvoicingEvents EInvoicingEvent[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([companyId])\n  @@index([status])\n  @@index([dueAt])\n  @@index([stripePaymentIntentId])\n  @@index([paymentToken])\n  @@index([companyId, status])\n  @@index([issuedAt]) // pour les rapports par période\n}\n\n// ============================================================\n// INVOICE LINE\n// ─────────────────────────────────────────────────────────────\n// Une ligne dans la facture. Même logique que QuoteLine.\n//\n// RELATIONS:\n// → Invoice (N:1) — appartient à une facture\n// → CatalogItem (N:1) optionnel — article du catalogue\n// ============================================================\n\nmodel InvoiceLine {\n  id        String  @id @default(cuid())\n  invoiceId String\n  invoice   Invoice @relation(fields: [invoiceId], references: [id], onDelete: Cascade)\n\n  catalogItemId String?\n  catalogItem   CatalogItem? @relation(fields: [catalogItemId], references: [id])\n\n  description String\n  reference   String?\n  quantity    Float    @default(1)\n  unitPrice   Float\n  tvaRate     Float    @default(20)\n  unit        ItemUnit @default(UNITE)\n  discount    Float    @default(0)\n  total       Float\n\n  position Int @default(0)\n\n  createdAt DateTime @default(now())\n\n  @@index([invoiceId])\n  @@index([catalogItemId])\n}\n\n// ============================================================\n// MESSAGE LOG (anciennement SmsLog)\n// ─────────────────────────────────────────────────────────────\n// Historique complet de tous les messages par client.\n// SMS + Email + WhatsApp (V2) dans un seul historique unifié.\n// Groupés par client pour former une conversation.\n//\n// RELATIONS:\n// → Company (N:1)\n// → Client (N:1) — conversation avec ce client\n// ============================================================\n\nmodel SmsLog {\n  id        String  @id @default(cuid())\n  companyId String\n  company   Company @relation(fields: [companyId], references: [id], onDelete: Cascade)\n  clientId  String\n  client    Client  @relation(fields: [clientId], references: [id])\n\n  direction   MessageDirection\n  channel     PreferredChannel @default(SMS) // SMS, EMAIL, WHATSAPP\n  body        String\n  subject     String? // objet email si channel=EMAIL\n  fromNumber  String? // null si channel=EMAIL\n  toNumber    String? // null si channel=EMAIL\n  fromEmail   String? // si channel=EMAIL\n  toEmail     String? // si channel=EMAIL\n  isRead      Boolean          @default(false)\n  readAt      DateTime?\n  deliveredAt DateTime?\n\n  // Identifiants externes selon le provider\n  twilioSid         String? @unique\n  whatsappMessageId String? @unique\n  emailMessageId    String? @unique\n  externalMessageId String?\n  status            String? // sent, delivered, read, failed, received\n\n  // Connexion de canal associée (multi-tenant)\n  whatsAppConnectionId String?\n  whatsAppConnection   WhatsAppConnection? @relation(fields: [whatsAppConnectionId], references: [id], onDelete: SetNull)\n  emailConnectionId    String?\n  emailConnection      EmailConnection?    @relation(fields: [emailConnectionId], references: [id], onDelete: SetNull)\n\n  // Threading Email\n  threadId   String?\n  inReplyTo  String?\n  references String?\n\n  // Pièces jointes (PDF factures, devis, fichiers...)\n  attachments Json?\n\n  // Type de message automatique envoyé par le système\n  autoType     String? // \"maintenance_reminder\", \"appointment_confirm\", \"manual\", \"bulk\"\n  templateName String?\n\n  // Erreurs éventuelles\n  errorCode    String?\n  errorMessage String?\n  metadata     Json?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @default(now()) @updatedAt\n\n  @@index([companyId])\n  @@index([clientId])\n  @@index([clientId, createdAt]) // pour charger la conversation chronologiquement\n  @@index([toNumber])\n  @@index([fromNumber]) // pour trouver le client à la réception d'un SMS\n  @@index([isRead])\n  @@index([channel])\n  @@index([threadId])\n  @@index([externalMessageId])\n}\n\n// ============================================================\n// WHATSAPP CONNECTION (MULTI-TENANT)\n// ─────────────────────────────────────────────────────────────\n// Connexion WhatsApp Business Cloud API par Company.\n// Permet à chaque installateur d'utiliser son propre numéro.\n// Supporte 1 ou N numéros par entreprise.\n// ============================================================\n\nmodel WhatsAppConnection {\n  id        String  @id @default(cuid())\n  companyId String\n  company   Company @relation(fields: [companyId], references: [id], onDelete: Cascade)\n\n  name                 String  @default(\"Principal\") // \"Général\", \"SAV\"\n  phoneNumberId        String // Phone Number ID Meta Graph API\n  wabaId               String? // WhatsApp Business Account ID Meta\n  displayPhoneNumber   String? // Ex: \"+33 6 12 34 56 78\"\n  verifiedName         String? // Nom officiel vérifié par Meta\n  qualityRating        String? // \"GREEN\", \"YELLOW\", \"RED\"\n  encryptedAccessToken String? // Token d'accès chiffré AES-256-GCM\n\n  status          String  @default(\"CONNECTED\") // CONNECTED, ERROR, REAUTH_REQUIRED, DISCONNECTED\n  isDefault       Boolean @default(true)\n  webhookVerified Boolean @default(true)\n\n  messages SmsLog[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([companyId, phoneNumberId])\n  @@index([phoneNumberId])\n  @@index([companyId])\n}\n\n// ============================================================\n// EMAIL CONNECTION (MULTI-TENANT)\n// ─────────────────────────────────────────────────────────────\n// Connexion Email (Google Workspace, Microsoft 365, SMTP) par Company.\n// ============================================================\n\nmodel EmailConnection {\n  id        String  @id @default(cuid())\n  companyId String\n  company   Company @relation(fields: [companyId], references: [id], onDelete: Cascade)\n\n  provider          String // \"GOOGLE\", \"MICROSOFT\", \"SMTP\"\n  emailAddress      String // \"contact@climpro.fr\"\n  displayName       String? // \"Dupont Climatisation\"\n  providerAccountId String? // ID du compte Google/Microsoft\n\n  encryptedAccessToken  String? // OAuth Access Token chiffré AES-256-GCM\n  encryptedRefreshToken String? // OAuth Refresh Token chiffré AES-256-GCM\n  tokenExpiresAt        DateTime?\n\n  smtpHost          String?\n  smtpPort          Int?\n  smtpUser          String?\n  encryptedSmtpPass String? // Pass chiffré AES-256-GCM\n\n  status     String    @default(\"CONNECTED\") // CONNECTED, ERROR, REAUTH_REQUIRED, DISCONNECTED\n  isDefault  Boolean   @default(true)\n  lastSyncAt DateTime?\n\n  messages SmsLog[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([companyId, emailAddress])\n  @@index([companyId])\n}\n\n// ============================================================\n// SMS USAGE\n// ─────────────────────────────────────────────────────────────\n// Compteur SMS mensuel par company.\n// Reset automatique chaque 1er du mois (cron).\n// Utilisé pour vérifier les limites du plan.\n//\n// RELATIONS:\n// → Company (N:1)\n// ============================================================\n\nmodel SmsUsage {\n  id        String  @id @default(cuid())\n  companyId String\n  company   Company @relation(fields: [companyId], references: [id], onDelete: Cascade)\n\n  month     Int // 1-12\n  year      Int\n  count     Int   @default(0) // SMS envoyés ce mois\n  extraCost Float @default(0) // coût SMS hors forfait\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([companyId, month, year])\n}\n\n// ============================================================\n// NOTIFICATION\n// ─────────────────────────────────────────────────────────────\n// Toutes les notifications envoyées aux users.\n// Un enregistrement par notification × canal.\n//\n// entityType + entityId permettent de naviguer vers\n// l'élément concerné en cliquant sur la notif.\n//\n// RELATIONS:\n// → Company (N:1)\n// → User (N:1) — destinataire\n// ============================================================\n\nmodel Notification {\n  id        String  @id @default(cuid())\n  companyId String\n  company   Company @relation(fields: [companyId], references: [id], onDelete: Cascade)\n  userId    String\n  user      User    @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  type    NotificationType\n  channel NotificationChannel\n  status  NotificationStatus  @default(PENDING)\n\n  title String\n  body  String\n\n  // Pour naviguer vers l'élément concerné\n  entityType String? // \"client\", \"intervention\", \"invoice\", \"quote\", \"sms\"\n  entityId   String?\n  data       Json? // données supplémentaires\n\n  isRead     Boolean   @default(false)\n  readAt     DateTime?\n  sentAt     DateTime?\n  failedAt   DateTime?\n  failReason String?\n\n  createdAt DateTime @default(now())\n\n  @@index([userId])\n  @@index([userId, isRead])\n  @@index([createdAt])\n}\n\n// ============================================================\n// QUOTE REQUEST\n// ─────────────────────────────────────────────────────────────\n// Demandes de devis depuis le formulaire public sur le site\n// de l'installateur. Pas besoin de compte client.\n//\n// RELATIONS:\n// → Company (N:1) — destinataire de la demande\n// ============================================================\n\nmodel QuoteRequest {\n  id        String  @id @default(cuid())\n  companyId String\n  company   Company @relation(fields: [companyId], references: [id], onDelete: Cascade)\n\n  firstName   String\n  lastName    String\n  phone       String\n  email       String?\n  address     String?\n  tradeSlug   String? // \"climatisation\", \"pompe-a-chaleur\"...\n  message     String?\n  isProcessed Boolean   @default(false)\n  processedAt DateTime?\n\n  createdAt DateTime @default(now())\n\n  @@index([companyId])\n  @@index([isProcessed])\n}\n\n// ============================================================\n// ACCOUNTING EXPORT\n// ─────────────────────────────────────────────────────────────\n// Exports comptables générés par la company.\n// Chaque export = un fichier Excel/CSV téléchargeable\n// contenant toutes les factures d'une période.\n//\n// Utilisé par:\n//   - Le comptable de l'installateur\n//   - L'installateur lui-même pour la déclaration TVA\n//   - L'intégration Pennylane/Indy (si activée)\n//\n// RELATIONS:\n// → Company (N:1)\n// ============================================================\n\nmodel AccountingExport {\n  id        String  @id @default(cuid())\n  companyId String\n  company   Company @relation(fields: [companyId], references: [id], onDelete: Cascade)\n\n  // Période couverte\n  periodStart DateTime\n  periodEnd   DateTime\n  periodLabel String // \"T1 2026\", \"Janvier 2026\", \"2026\"\n  type        AccountingExportType\n\n  // Fichier généré\n  fileUrl  String? // URL du fichier Excel/CSV sur Cloudinary\n  fileName String? // \"export-comptable-T1-2026.xlsx\"\n\n  // Totaux calculés (snapshot au moment de l'export)\n  totalHT      Float @default(0)\n  totalTva0    Float @default(0) // TVA 0%\n  totalTva55   Float @default(0) // TVA 5.5%\n  totalTva10   Float @default(0) // TVA 10%\n  totalTva20   Float @default(0) // TVA 20%\n  totalTvaAll  Float @default(0) // Total TVA collectée\n  totalTTC     Float @default(0)\n  invoiceCount Int   @default(0) // nb factures incluses\n  paidCount    Int   @default(0) // nb factures payées\n\n  // Intégration externe\n  pennylaneExportedAt DateTime? // si envoyé vers Pennylane\n  indyExportedAt      DateTime? // si envoyé vers Indy\n\n  createdAt DateTime @default(now())\n\n  @@index([companyId])\n  @@index([companyId, periodStart])\n}\n\n// ============================================================\n// TVA SUMMARY\n// ─────────────────────────────────────────────────────────────\n// Résumé TVA calculé automatiquement chaque trimestre.\n// Affiché dans l'interface pour aider l'installateur\n// à remplir sa déclaration sur impots.gouv.fr\n//\n// RELATIONS:\n// → Company (N:1)\n// ============================================================\n\nmodel TvaSummary {\n  id        String  @id @default(cuid())\n  companyId String\n  company   Company @relation(fields: [companyId], references: [id], onDelete: Cascade)\n\n  // Trimestre: Q1=1, Q2=2, Q3=3, Q4=4\n  quarter Int\n  year    Int\n\n  // Montants TVA collectée (sur factures payées)\n  caHT     Float @default(0) // chiffre d'affaires HT\n  tva0     Float @default(0)\n  tva55    Float @default(0)\n  tva10    Float @default(0)\n  tva20    Float @default(0)\n  totalTva Float @default(0) // total TVA à déclarer\n\n  // Statut déclaration\n  isDeclared Boolean   @default(false)\n  declaredAt DateTime?\n  declaredBy String? // userId\n\n  // Dates du trimestre\n  periodStart DateTime\n  periodEnd   DateTime\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([companyId, quarter, year])\n  @@index([companyId])\n}\n\n// ============================================================\n// ACCOUNTING INTEGRATION\n// ─────────────────────────────────────────────────────────────\n// Connexion avec logiciels comptables tiers (Pennylane, Indy)\n// Chaque company peut connecter un logiciel comptable.\n// Les factures sont envoyées automatiquement après création/paiement.\n//\n// RELATIONS:\n// → Company (1:1)\n// ============================================================\n\nmodel AccountingIntegration {\n  id        String  @id @default(cuid())\n  companyId String  @unique\n  company   Company @relation(fields: [companyId], references: [id], onDelete: Cascade)\n\n  provider AccountingProvider // PENNYLANE, INDY, QUICKBOOKS, NONE\n\n  // Credentials chiffrées (AES-256)\n  apiKey         String? // clé API chiffrée\n  apiSecret      String? // secret chiffré\n  organizationId String? // ID organisation chez le provider\n\n  isActive      Boolean   @default(true)\n  lastSyncAt    DateTime?\n  lastSyncError String?\n\n  // Mapping: quand envoyer automatiquement\n  syncOnCreate Boolean @default(false) // à la création de la facture\n  syncOnSend   Boolean @default(true) // à l'envoi au client\n  syncOnPaid   Boolean @default(true) // au paiement\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n// ============================================================\n// INVOICE PAYMENT EVENT\n// ─────────────────────────────────────────────────────────────\n// Historique des événements de paiement en ligne pour chaque facture.\n// Créé automatiquement via webhook Stripe.\n//\n// Permet de tracer tout le cycle de paiement:\n//   checkout.created → link_opened → payment_succeeded/failed\n//\n// RELATIONS:\n// → Invoice (N:1) — appartient à une facture\n// ============================================================\n\nmodel InvoicePaymentEvent {\n  id        String  @id @default(cuid())\n  invoiceId String\n  invoice   Invoice @relation(fields: [invoiceId], references: [id], onDelete: Cascade)\n\n  // Type d'événement Stripe\n  event String // \"checkout.created\", \"checkout.expired\",\n  // \"payment.succeeded\", \"payment.failed\",\n  // \"payment.refunded\"\n\n  amount   Float? // montant concerné\n  currency String @default(\"EUR\")\n\n  // Données Stripe brutes\n  stripeEventId String? @unique\n  stripeData    Json?\n\n  // IP du client au moment du paiement\n  clientIp String?\n\n  createdAt DateTime @default(now())\n\n  @@index([invoiceId])\n}\n\n// ============================================================\n// AUDIT LOG\n// ─────────────────────────────────────────────────────────────\n// Historique de toutes les actions importantes.\n// Permet de savoir qui a fait quoi et quand.\n// Conservé pendant 1 an puis archivé.\n//\n// RELATIONS:\n// → Company (N:1)\n// → User (N:1) optionnel — qui a fait l'action\n// ============================================================\n\nmodel AuditLog {\n  id        String  @id @default(cuid())\n  companyId String\n  company   Company @relation(fields: [companyId], references: [id], onDelete: Cascade)\n  userId    String?\n  user      User?   @relation(fields: [userId], references: [id])\n\n  action     String // \"client.created\", \"invoice.paid\", \"intervention.completed\"\n  entityType String // \"Client\", \"Invoice\", \"Intervention\"\n  entityId   String\n  oldData    Json? // état avant modification\n  newData    Json? // état après modification\n  ipAddress  String?\n\n  createdAt DateTime @default(now())\n\n  @@index([companyId])\n  @@index([entityType, entityId])\n  @@index([createdAt])\n}\n\n// ============================================================\n// SUPER ADMIN\n// ─────────────────────────────────────────────────────────────\n// Rôle système pour le créateur de la plateforme.\n// Complètement séparé des Company/User normaux.\n// Accès à /admin/* uniquement.\n//\n// SystemRole:\n//   SUPER_ADMIN → accès total: stats, impersonate, bloquer\n//   SUPPORT     → lecture seule: voir companies, aider clients\n//\n// RELATIONS:\n// → AdminSession (1:N) — sessions actives\n// → AdminAuditLog (1:N) — toutes ses actions\n// ============================================================\n\nmodel AdminUser {\n  id          String     @id @default(cuid())\n  email       String     @unique\n  password    String // bcrypt hash\n  firstName   String\n  lastName    String\n  systemRole  SystemRole @default(SUPPORT)\n  isActive    Boolean    @default(true)\n  lastLoginAt DateTime?\n\n  refreshTokenHash String?\n\n  sessions  AdminSession[]\n  auditLogs AdminAuditLog[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n// ============================================================\n// ADMIN SESSION\n// Sessions actives des admins (refresh tokens)\n// ============================================================\n\nmodel AdminSession {\n  id          String    @id @default(cuid())\n  adminUserId String\n  adminUser   AdminUser @relation(fields: [adminUserId], references: [id], onDelete: Cascade)\n\n  refreshTokenHash String\n  device           String?\n  ipAddress        String?\n  expiresAt        DateTime\n  lastUsedAt       DateTime @default(now())\n\n  createdAt DateTime @default(now())\n}\n\n// ============================================================\n// ADMIN AUDIT LOG\n// Toutes les actions des admins (qui a fait quoi sur quelle company)\n// ============================================================\n\nmodel AdminAuditLog {\n  id          String    @id @default(cuid())\n  adminUserId String\n  adminUser   AdminUser @relation(fields: [adminUserId], references: [id])\n\n  action     String // \"company.blocked\", \"company.impersonated\", \"plan.changed\"\n  targetType String // \"Company\", \"Subscription\", \"User\"\n  targetId   String\n  details    Json?\n  ipAddress  String?\n\n  createdAt DateTime @default(now())\n\n  @@index([adminUserId])\n  @@index([targetType, targetId])\n}\n\n// ============================================================\n// FACTURATION ÉLECTRONIQUE (RÉFORME FR 2026 / 2027)\n// ============================================================\n\n// ── CONNEXION PLATEFORME AGRÉÉE ──────────────────────────────\nmodel EInvoicingConnection {\n  id        String  @id @default(cuid())\n  companyId String  @unique\n  company   Company @relation(fields: [companyId], references: [id], onDelete: Cascade)\n\n  provider          EInvoicingProviderType     @default(B2BROUTER)\n  providerAccountId String? // Account ID chez le provider (ex: B2Brouter project/account ID)\n  environment       String                     @default(\"sandbox\") // \"sandbox\" | \"production\"\n  status            EInvoicingConnectionStatus @default(DISCONNECTED)\n\n  // Credentials chiffrées (AES-256-GCM) — JAMAIS stockées en clair\n  apiKeyEncrypted       String?\n  apiSecretEncrypted    String?\n  accessTokenEncrypted  String?\n  refreshTokenEncrypted String?\n  tokenExpiresAt        DateTime?\n\n  // Paramètres fonctionnels\n  receivingEnabled Boolean @default(true) // Obligatoire à partir du 1er sept 2026\n  emissionEnabled  Boolean @default(false) // B2B outgoing (généralisé 2027)\n  autoSyncIncoming Boolean @default(true)\n\n  lastSyncAt    DateTime?\n  lastSyncError String?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([companyId])\n  @@index([status])\n}\n\n// ── FACTURES FOURNISSEURS REÇUES (INCOMING E-INVOICES) ────────\nmodel ReceivedInvoice {\n  id        String  @id @default(cuid())\n  companyId String\n  company   Company @relation(fields: [companyId], references: [id], onDelete: Cascade)\n\n  provider          EInvoicingProviderType @default(B2BROUTER)\n  providerInvoiceId String // ID facture chez le provider\n\n  // Fournisseur (Émetteur)\n  supplierName       String\n  supplierSiren      String?\n  supplierSiret      String?\n  supplierVatNumber  String?\n  supplierAddress    String?\n  supplierCity       String?\n  supplierPostalCode String?\n  supplierCountry    String? @default(\"FR\")\n  supplierEmail      String?\n\n  // Facture\n  invoiceNumber String\n  issueDate     DateTime\n  dueDate       DateTime?\n  currency      String    @default(\"EUR\")\n\n  // Montants\n  totalHT  Float\n  totalVAT Float\n  totalTTC Float\n\n  // Statut\n  status EInvoicingStatus @default(RECEIVED) // RECEIVED, ACCEPTED, REJECTED, PAID, CANCELLED\n\n  // Données structurées et document PDF / Factur-X\n  structuredData Json? // Données sémantiques normalisées EN 16931 / UBL / CII\n  documentUrl    String? // URL document téléchargeable (PDF / XML / Factur-X)\n  rawFormat      String? // \"Factur-X\", \"UBL\", \"CII\", \"JSON\"\n\n  receivedAt DateTime @default(now())\n  createdAt  DateTime @default(now())\n  updatedAt  DateTime @updatedAt\n\n  events EInvoicingEvent[]\n\n  @@unique([companyId, provider, providerInvoiceId])\n  @@index([companyId])\n  @@index([status])\n  @@index([issueDate])\n  @@index([supplierSiret])\n}\n\n// ── JOURNAL D'ÉVÉNEMENTS & WEBHOOKS FACTURATION ÉLECTRONIQUE ───\nmodel EInvoicingEvent {\n  id        String  @id @default(cuid())\n  companyId String\n  company   Company @relation(fields: [companyId], references: [id], onDelete: Cascade)\n\n  invoiceId         String?\n  invoice           Invoice?         @relation(fields: [invoiceId], references: [id], onDelete: Cascade)\n  receivedInvoiceId String?\n  receivedInvoice   ReceivedInvoice? @relation(fields: [receivedInvoiceId], references: [id], onDelete: Cascade)\n\n  provider          String // \"B2BROUTER\", etc.\n  providerInvoiceId String?\n  eventType         String // \"invoice.received\", \"invoice.status_changed\", \"invoice.rejected\", \"payment.recorded\"\n  providerStatus    String?\n\n  idempotencyKey String? @unique // Pour idempotence des webhooks\n  payloadJson    Json?\n  errorMessage   String?\n\n  receivedAt  DateTime  @default(now())\n  processedAt DateTime?\n\n  createdAt DateTime @default(now())\n\n  @@index([companyId])\n  @@index([invoiceId])\n  @@index([receivedInvoiceId])\n  @@index([eventType])\n}\n\n// ── FILE DE TÂCHES ASYNCHRONES PERSISTANTE (JOB QUEUE) ────────\nmodel EInvoicingJob {\n  id        String  @id @default(cuid())\n  companyId String\n  company   Company @relation(fields: [companyId], references: [id], onDelete: Cascade)\n\n  type    EInvoicingJobType\n  payload Json\n  status  EInvoicingJobStatus @default(PENDING) // PENDING, PROCESSING, COMPLETED, FAILED\n\n  attempts    Int       @default(0)\n  maxAttempts Int       @default(5)\n  nextRunAt   DateTime  @default(now())\n  lockedAt    DateTime?\n  lockedBy    String?\n  lastError   String?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([status, nextRunAt])\n  @@index([companyId])\n}\n\n// ============================================================\n// INVOICE TRANSACTION (Factures)\n// ─────────────────────────────────────────────────────────────\n// Historique des transactions de règlement pour les factures.\n// ============================================================\n\nmodel InvoiceTransaction {\n  id        String  @id @default(cuid())\n  invoiceId String\n  invoice   Invoice @relation(fields: [invoiceId], references: [id], onDelete: Cascade)\n  companyId String\n  company   Company @relation(fields: [companyId], references: [id], onDelete: Cascade)\n\n  type     InvoicePaymentMethodType\n  status   String                   @default(\"succeeded\") // succeeded, failed, pending\n  amount   Float\n  currency String                   @default(\"EUR\")\n\n  stripePaymentIntentId   String? @unique\n  stripeCheckoutSessionId String? @unique\n  stripeTransferId        String?\n  bankReference           String?\n\n  paidAt    DateTime?\n  createdAt DateTime  @default(now())\n\n  @@index([invoiceId])\n  @@index([companyId])\n  @@index([stripePaymentIntentId])\n  @@index([stripeCheckoutSessionId])\n}\n\n// ============================================================\n// STRIPE FEE CONFIG\n// ─────────────────────────────────────────────────────────────\n// Tarification Stripe dynamique et configurable.\n// ============================================================\n\nmodel StripeFeeConfig {\n  id       String  @id @default(cuid())\n  feeRate  Float   @default(0.015) // 1.5%\n  fixedFee Float   @default(0.25) // 0.25€\n  currency String  @default(\"EUR\")\n  isActive Boolean @default(true)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n// ============================================================\n// OPEN BANKING — CONNEXION BANCAIRE (POWENS / GOCARDLESS)\n// ============================================================\n\nmodel BankConnection {\n  id        String  @id @default(cuid())\n  companyId String  @unique\n  company   Company @relation(fields: [companyId], references: [id], onDelete: Cascade)\n\n  provider     String // \"POWENS\", \"GOCARDLESS\"\n  connectionId String\n  userId       String?\n\n  accessTokenEncrypted  String?\n  refreshTokenEncrypted String?\n  tokenExpiresAt        DateTime?\n  status                String    @default(\"PENDING\") // PENDING, ACTIVE, ERROR, DISCONNECTED\n  lastSyncAt            DateTime?\n\n  accounts BankAccount[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([companyId])\n}\n\nmodel BankAccount {\n  id               String         @id @default(cuid())\n  bankConnectionId String\n  bankConnection   BankConnection @relation(fields: [bankConnectionId], references: [id], onDelete: Cascade)\n  companyId        String\n  company          Company        @relation(fields: [companyId], references: [id], onDelete: Cascade)\n\n  externalId  String\n  iban        String?\n  bic         String?\n  accountName String?\n  balance     Float?\n  currency    String  @default(\"EUR\")\n\n  transactions BankTransaction[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([companyId])\n}\n\nmodel BankTransaction {\n  id            String      @id @default(cuid())\n  bankAccountId String\n  bankAccount   BankAccount @relation(fields: [bankAccountId], references: [id], onDelete: Cascade)\n  companyId     String\n  company       Company     @relation(fields: [companyId], references: [id], onDelete: Cascade)\n\n  externalTransactionId String    @unique\n  amount                Float\n  currency              String    @default(\"EUR\")\n  label                 String?\n  reference             String?\n  counterparty          String?\n  counterpartyIban      String?\n  transactionDate       DateTime\n  valueDate             DateTime?\n\n  reconciliationStatus String?   @default(\"PENDING\") // MATCHED, PROBABLE, IGNORED, PENDING\n  confidenceScore      Float? // 0.0 → 1.0\n  matchedInvoiceId     String?\n  matchedInvoice       Invoice?  @relation(fields: [matchedInvoiceId], references: [id], onDelete: SetNull)\n  reconciledAt         DateTime?\n  reconciledBy         String? // \"AUTO\" | userId\n\n  createdAt DateTime @default(now())\n\n  @@index([companyId])\n  @@index([externalTransactionId])\n  @@index([matchedInvoiceId])\n}\n"
}

